    blurb: { ko: '-(으)나 마나와 -아/어 봤자를 통해 이미 정해진 뻔한 결과, 애써 노력해도 소용없는 헛수고와 체념의 감정을 실감 나게 표현합니다.', en: 'Express foregone obvious conclusions (-(으)나 마나) and the futility of useless efforts (-아/어 봤자).' },
