    blurb: { ko: '-(으)ㄹ걸 그랬다와 -았/었어야 했는데를 통해 지나간 행동에 대한 아쉬움, 마땅한 도리를 다하지 못한 자책과 사과를 진솔하게 표현합니다.', en: 'Express soft personal regrets (-(으)ㄹ걸 그랬다) and heavy self-blame or polite apologies (-았/었어야 했는데).' },
